// Reads
// ----------------------------------------------------------------------------

/** The template with this key, or `null` — never a throw, because the key
 *  arrives from a client and an unknown one is a refusal, not a crash. */
export function findTaskTemplate(key: string): TaskTemplate | null {
  return TASK_TEMPLATES.find((template) => template.key === key) ?? null;
}

/** How many tasks importing this template would create. */
export function taskTemplateSize(template: TaskTemplate): number {
  return template.items.length;
}

/**
 * How the product says a number of tasks out loud: `"1 task"`, `"9 tasks"`.
 *
 * ONE decision, in one place. It was written out three times — the catalog
 * picker, the phase prompt's server component, and the prompt's client island —
 * and the third copy arrived only because the partial-import receipt moved into
 * the island and nobody noticed the file two doors down already had it. Three
 * copies of one sentence is three chances for the product to count differently
 * on three screens.
 *
 * It lives HERE and not beside a component because this module is the db-free
 * half of the pair (see the note above `UNKNOWN_TEMPLATE_ERROR`): the `"use
 * client"` island already imports `TEMPLATES_ROUTE` from it, so one more export
 * ships nothing new to the browser.
 */
export function taskCountLabel(count: number): string {
  return count === 1 ? "1 task" : `${count} tasks`;
}

/**
 * The priority an item will be created with: its own, or its template's.
 *
 * One function so the picker's preview and the import cannot disagree about
 * what is about to be created.
 */
export function taskTemplateItemPriority(
  template: TaskTemplate,
  item: TaskTemplateItem
): TaskPriority {
  return item.priority ?? template.defaultPriority;
}

/** A phase and the templates that belong to it. */
export interface TaskTemplatePhaseGroup {
  phase: PhaseNumber;
  /** The phase's display name, from the one place phases are named. */
  phaseName: string;
  templates: readonly TaskTemplate[];
}

const PHASE_NUMBERS = Object.keys(PHASES)
  .map(Number)
  .sort((a, b) => a - b) as PhaseNumber[];

/**
 * The templates that belong to a phase, in catalog order.
 *
 * ONE decision, and it lives with the catalog. "Which templates belong to a
 * phase" was written out twice — here and again in the T-020 phase prompt —
 * over the same array. The two could not disagree while both read this literal,
 * but the header above says what happens next: the day church-authored
 * templates arrive, this module becomes the `is_system` half of a union and
 * gains a second source. One reader would have picked the new rows up and the
 * other — the prompt, which decides what a stage change OFFERS — silently would
 * not. `taskTemplatesByPhase` calls this, so there is exactly one filter.
 *
 * Returns `[]` for a phase the catalog says nothing about, which is what makes
 * "a phase with no templates prompts nothing" fall out of the data rather than
 * out of a special case. Every phase 0–6 carries a template today
 * (`templates.test.ts` asserts it), so the empty answer is the guard for a
 * phase number the catalog has not caught up with.
 */
export function phaseTemplatesFor(phase: number): TaskTemplate[] {
  return TASK_TEMPLATES.filter((template) => template.phase === phase);
}

/**
 * The catalog grouped for display: every phase in order, each with its
 * templates in catalog order.
 *
 * Every phase appears, because a phase with no checklist is worth seeing as an
 * empty heading rather than silently vanishing — the catalog test asserts none
 * are empty today, so an empty group means someone removed a template.
 */
export function taskTemplatesByPhase(): TaskTemplatePhaseGroup[] {
  return PHASE_NUMBERS.map((phase) => ({
    phase,
    phaseName: PHASES[phase],
    templates: phaseTemplatesFor(phase),
  }));
}

